//! Deliberately cloneable hosted classic Heartbeat owners.

#[derive(Clone, Copy)]
struct PreparedClassicHeartbeat;
#[derive(Clone, Copy)]
struct ClassicHeartbeatDriverOwner;
#[derive(Clone, Copy)]
struct ClassicHeartbeatAcceptanceFailure;
#[derive(Clone, Copy)]
struct ClassicHeartbeatSuccessor;
#[derive(Clone, Copy)]
struct ClassicHeartbeatExecutionState;
#[derive(Clone, Copy)]
struct ClassicHeartbeatExecution;
#[derive(Clone, Copy)]
struct PreparedClassicHeartbeatInstall;
#[derive(Clone, Copy)]
struct ClassicHeartbeatInterpretationFailure;
